        let unitsPerPixel = parameterSpan;
        let unitScale = select(dashUnitsPerPoint, 1.0, dashInTileUnits > 0.5);
        let dashUnits = dashLengthPoints * unitScale;
        let gapUnits = lineStyle.w * unitScale;
        let period = dashUnits + gapUnits;
